------- DQL LEVEL 2 -------

-- 1. Find total number of products and average product price for every brand.
SELECT COUNT(product_name) FROM product_info;
SELECT brand_name, AVG(list_price)
FROM product_info P JOIN brand_info B
ON P.brand_id = B.brand_id 
GROUP BY  brand_name


-- 2. Calculate total net revenue generated by each product category.
SELECT C.category_name, SUM(O.quantity * O.list_price * (1 - discount)) AS total_net_revenue FROM 
order_item_info O JOIN product_info P ON O.product_id=P.product_id 
JOIN category_info C ON P.category_id=C.category_id
GROUP BY C.category_name


-- 3. Calculate total orders, net rev, avg order per month
SELECT * FROM order_info
SELECT * FROM order_item_info
-- SSMS --
SELECT YEAR(order_date) AS order_year ,COUNT(item_id) AS total_orders FROM order_item_info OI
JOIN order_info O ON OI.order_id=O.order_id
GROUP BY YEAR(order_date)

 -- PG --
SELECT EXTRACT(YEAR FROM O.order_date), COUNT(item_id) AS total_orders FROM order_item_info OI
JOIN order_info O ON OI.order_id=O.order_id
GROUP BY EXTRACT(YEAR FROM O.order_date)


-- 4. Find top 5 customers generated highest revenue
SELECT C.first_name, C.last_name, OI.list_price*quantity*(1-discount) as Rev_Generated
FROM customer_info C JOIN order_info O 
ON C.customer_id=O.customer_id 
JOIN order_item_info OI on O.order_id=OI.order_id
ORDER BY Rev_Generated DESC LIMIT 5


-- 5. Find brands having: More than 20 products & Average product price above $600.
SELECT B.brand_name, AVG(P.list_price) 
FROM product_info P JOIN brand_info B
ON P.brand_id=B.brand_id
GROUP BY B.brand_name
HAVING COUNT(P.brand_id) > 20 AND AVG(P.list_price) > 600


-- 6. Find products that have never appeared in order_items.
SELECT P.product_id, OI.product_id, P.product_name, P.list_price  FROM product_info P 
LEFT JOIN order_item_info OI
ON P.product_id=OI.product_id
WHERE OI.product_id IS NULL
ORDER BY P.product_id ASC


-- 7. Multi table sales report : Display customer full name, Order id, product name, brand name, quantity, discount net rev.
SELECT C.customer_id, C.first_name, C.last_name, O.order_id, P.product_name, B.brand_name, OI.quantity*OI.list_price*(1-OI.discount) as revenue
FROM customer_info C join order_info O 
ON C.customer_id=O.customer_id
JOIN order_item_info OI ON O.order_id=OI.order_id
JOIN product_info P ON P.product_id=OI.product_id
JOIN brand_info B ON P.brand_id=B.brand_id


-- 8. Display product name, store ID, avialable stock quantity Include products without inventory records and inventory records without matching products.
SELECT P.product_name, S.store_id, S.quantity, P.list_price
FROM product_info P
LEFT JOIN stock_info S ON P.product_id=S.product_id
WHERE P.product_name = 'Haro Shredder Pro 20 - 2017'

-- 9. SELECT products using case when, categorize them in 3 parts exp, okish and cheap and count each.
SELECT P.product_name, P.list_price,
    COUNT(CASE WHEN list_price >= 500 THEN 1 END) AS exp,
    COUNT(CASE WHEN list_price >= 200 AND list_price <500 THEN 1 END) AS okish,
    COUNT(CASE WHEN list_price <= 200 THEN 1 END) AS cheap
FROM product_info P
LEFT JOIN stock_info S ON P.product_id=S.product_id
GROUP BY P.product_name, P.list_price



-- 10. FINAL : Complete business intlligence business report.
SELECT S.store_name, COUNT(DISTINCT O.order_id)AS total_orders,  COUNT(DISTINCT O.customer_id)
AS uniqu_customer, SUM(OI.quantity) AS total_items , SUM(OI.quantity*OI.list_price*(1-OI.discount)) as total_rev ,
AVG(OI.list_price*OI.quantity*(1-OI.discount)) as avg_order_value
FROM
store_info S 
LEFT JOIN order_info O ON S.store_id=O.store_id 
     JOIN order_item_info OI ON O.order_id=OI.order_id
GROUP BY S.store_name


SELECT * FROM customer_info
SELECT * FROM order_info
SELECT * FROM order_item_info

SELECT
    S.store_name,

    -- 1. Total orders
    (
        SELECT COUNT(*)
        FROM order_info O
        WHERE O.store_id = S.store_id
    ) AS total_orders,

    -- 2. Unique customers
    (
        SELECT COUNT(DISTINCT O.customer_id)
        FROM order_info O
        WHERE O.store_id = S.store_id
    ) AS unique_customers,

    -- 3. Total products sold
    (
        SELECT COALESCE(SUM(OI.quantity), 0)
        FROM order_info O
        JOIN order_item_info OI
            ON O.order_id = OI.order_id
        WHERE O.store_id = S.store_id
    ) AS total_products_sold,

    -- 4. Total net revenue
    (
        SELECT COALESCE(
            SUM(OI.quantity * OI.list_price * (1 - OI.discount)), 0
        )
        FROM order_info O
        JOIN order_item_info OI
            ON O.order_id = OI.order_id
        WHERE O.store_id = S.store_id
    ) AS total_net_revenue,

    -- 5. Average order value
    (
        SELECT COALESCE(
            SUM(OI.quantity * OI.list_price * (1 - OI.discount))
            / NULLIF(COUNT(DISTINCT O.order_id), 0), 0
        )
        FROM order_info O
        JOIN order_item_info OI
            ON O.order_id = OI.order_id
        WHERE O.store_id = S.store_id
    ) AS avg_order_value,

    -- 6. Active employees
    (
        SELECT COUNT(*)
        FROM staff_info SF
        WHERE SF.store_id = S.store_id
          AND SF.active = 1
    ) AS active_employees,

    -- 7. Inventory units
    (
        SELECT COALESCE(SUM(ST.quantity), 0)
        FROM stock_info ST
        WHERE ST.store_id = S.store_id
    ) AS inventory_units,

    -- 8. Inventory valuation
    (
        SELECT COALESCE(SUM(ST.quantity * P.list_price), 0)
        FROM stock_info ST
        JOIN product_info P
            ON ST.product_id = P.product_id
        WHERE ST.store_id = S.store_id
    ) AS inventory_valuation,

    -- 9. Revenue per employee
    (
        SELECT
            SUM(OI.quantity * OI.list_price * (1 - OI.discount))
            / NULLIF(
                (SELECT COUNT(*)
                 FROM staff_info SF
                 WHERE SF.store_id = S.store_id
                   AND SF.active = 1), 0
            )
        FROM order_info O
        JOIN order_item_info OI
            ON O.order_id = OI.order_id
        WHERE O.store_id = S.store_id
    ) AS revenue_per_employee

FROM store_info S
ORDER BY total_net_revenue DESC;
